  {t="C", q=349, obj=1, name="Stranglethorn Fever", gv="Collect", gw="Gorilla Fang", z=33, x=35.09, y=60.75, note="Collect Gorilla Fang", tip="The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang.", section="Stranglethorn Vale & Swamp of Sorrows (39-43)", zoneName="Stranglethorn Vale", p=1024, place="Mistvale gorillas"}, -- 2860
  {t="T", q=349, name="Stranglethorn Fever", z=33, x=35.27, y=60.41, target={kind="npc", id=1449, name="Witch Doctor Unbagwa"}, note="Inside Spirit Den", tip="Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then Mokk. Fight them one at a time.", section="Stranglethorn Vale & Swamp of Sorrows (39-43)", zoneName="Stranglethorn Vale", p=1025, place="Witch Doctor Unbagwa"}, -- 2861
