  {t="A", q=3161, name="Gahz'ridian", z=440, x=52.71, y=45.92, target={kind="npc", id=7771, name="Marvon Rivetseeker"}, tip="West along the road south; Marvon camps by the ruins at the Broken Pillar. Put on his Gahz'ridian Detector: it shows the buried ornaments, here and around the Dunemaul Compound.", section="Tanaris & Searing Gorge (47-48)", zoneName="Tanaris", p=1180, place="Marvon Rivetseeker"}, -- 3238
  {t="C", q=3161, obj=1, name="Gahz'ridian", gv="Collect", gw="Gahz'ridian Ornament", z=440, x=52.3, y=45.3, note="Collect Gahz'ridian Ornament", tip="South of the Noxious Lair the Dunemaul ogres hold their compound, with Gor'marok the Ravager at its eastern end. Dig up Gahz'ridian ornaments between the fights.", section="Tanaris & Searing Gorge (47-48)", zoneName="Tanaris", p=1181, place="Broken Pillar: kill these as you meet them"}, -- 3239
