  {t="A", q=1560, name="Tooga's Quest", z=440, x=30, y=65, target={kind="npc", id=5955, name="Tooga"}, note="Tooga", tip="Tooga waits in the valley. Walk him all the way to his wife Torta in Steamwheedle Port, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. Yeh'kinya stands in the port too.", section="Tanaris & Searing Gorge (47-48)", zoneName="Tanaris", p=1183, place="Tooga's escort"}, -- 3247
  {t="C", q=1560, name="Tooga's Quest", z=440, x=66.58, y=25.67, section="Tanaris & Searing Gorge (47-48)", zoneName="Tanaris", p=1183, place="Tooga's escort"}, -- 3248
  {t="C", q=82, obj=1, name="Noxious Lair Investigation", gv="Collect", gw="Centipaar Insect Parts", z=440, x=36.72, y=39.99, note="Collect Centipaar Insect Parts", tip="Careful: Centipaar Swarmers cast Silithid Swarm both in and out of combat, which brings small adds that interrupt you.", section="Tanaris & Searing Gorge (47-48)", zoneName="Tanaris", p=1184, place="The Noxious Lair"}, -- 3249
  {t="T", q=1560, name="Tooga's Quest", z=440, x=66.58, y=25.67, target={kind="npc", id=6015, name="Torta"}, note="Torta, Steamwheedle Port", section="Tanaris & Searing Gorge (47-48)", zoneName="Tanaris", p=1185, place="Steamwheedle Port"}, -- 3250
